import {glossary} from './localization.js';
import {config,gameId,clone,isDone,count,nextStep,edit,undoEdit,envelope,importData,differences,applyDifferences} from './model.js';
const source=import.meta.url.includes('/dist/');
const {createChineseText}=await import(new URL(source?'../../../shared/chinese-text.js':'../../shared/chinese-text.js',import.meta.url));
const chinese=createChineseText(glossary);let searchIndex=new Map();
const {createStore}=await import(new URL(source?'../../../shared/roadmap-store.js':'../../shared/roadmap-store.js',import.meta.url));
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={roadmap:'遊玩路線',collections:'蒐集查漏',trophies:'PS5 獎盃',backup:'資料與來源'};
const kinds={equipment:'原版裝備',puzzle:'解謎石',secret:'隱藏物',ripple:'人魚水點',lost:'失物',book:'戀愛書籍',key:'黃金鑰匙',spell:'魔法',bounty:'懸賞',encounter:'Aelius 對話',quest:'支線回報','ship-passive':'船被動（集合待核）',cannonpaw:'船炮彈',reward:'解謎獎勵箱'};
const params=()=>new URL(location.href).searchParams,view=()=>Object.hasOwn(names,params().get('view'))?params().get('view'):'roadmap';
let data,progress,ready=false,busy=false,refreshPending=false,review,lastUndo,retry,search='',status='all',category='equipment',target='',subtype='';const peeks=new Set();
const message=s=>$('feedback').textContent=s;
const store=createStore(config,{clone},()=>{if(!ready)return;if(busy){refreshPending=true;return;}refresh().catch(e=>message('更新失敗：'+e.message));});
function drainUpdates(){if(refreshPending){refreshPending=false;refresh().catch(e=>message(e.message));}}
async function refresh(){progress=await store.get();if(review&&JSON.stringify(progress)!==review.stamp){review.expired=true;$('import-status').textContent='預覽已過期，請重新比較。';gate();}render(true);}
const href=(v,extra={})=>'?'+new URLSearchParams({view:v,...extra});
const link=(v,label,extra={})=>`<a data-route href="${esc(href(v,extra))}">${esc(label)}</a>`;
const chapter=()=>data.chapters.find(c=>c.id===params().get('chapter'))||data.chapters[0];
function inline(text){return esc(text).replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\[S(\d+)\]/g,(_,n)=>link('backup','[S'+n+']',{target:'source-S'+n}));}
function markdown(text){return String(text||'').split('\n').filter(s=>s.trim()).map(s=>'<p>'+inline(s.replace(/^- /,''))+'</p>').join('');}
const check=(g,id,label)=>`<label class="check"><input id="${esc(g+'-'+id)}" type="checkbox" data-group="${g}" data-id="${esc(id)}" ${isDone(progress,g,id)?'checked':''}><span>${esc(label)}</span></label>`;
const options=(rows,value)=>rows.map(([id,label])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('');
const match=(r,g)=> (!target||target===r.id)&&(!search||(searchIndex.get(r.id)||JSON.stringify(r)).toLowerCase().includes(search.toLowerCase()))&&(status==='all'||isDone(progress,g,r.id)===(status==='done'));
function toolbar(){return `<div class="toolbar"><label>搜尋名稱、地區或 ID<input id="search" type="search" value="${esc(search)}" placeholder="例如 Purvanna、Bird Poop、cq3-book"></label><label>顯示<select id="status">${options([['pending','未完成'],['all','全部'],['done','已完成']],status)}</select></label><button data-reset>重設條件</button></div>`;}
const empty=()=>'<p class="empty">本條件沒有缺項或符合項目。<button data-reset>重設條件</button> <button data-all>查看全部</button></p>';
function sources(r){return '<span class="source-mark">'+(r.sourceIds||[]).map(id=>link('backup',id,{target:'source-'+id})).join(' · ')+'</span>';}
function routeFor(r){const s=data.steps.find(s=>s.id===r.route);return s?link('roadmap','回路線 · '+s.label,{chapter:s.chapterId,target:r.id}):'';}
const evidenceNames={'cross-checked':'多來源對照（非實機）','single-source':'單源／細部待核','conflicting':'來源有差異 · 待核對',pending:'位置待核對','spec-reviewed':'規格整理'};
function entity(r,embedded=false){const done=isDone(progress,'facts',r.id),hasGuide=Array.isArray(r.instructions),detail=`${r.prerequisites?.length?'<p><strong>前置：</strong>'+r.prerequisites.map(inline).join('；')+'</p>':''}${hasGuide?'<ol>'+r.instructions.map(s=>'<li>'+inline(s)+'</li>').join('')+'</ol>':''}${r.review?'<p><strong>本次補查：</strong>'+inline(r.review.result)+'</p><p>仍待核對：'+inline(r.review.remaining)+'</p>':''}`;return `<article class="${embedded?'entity-line':'row'} ${done?'done':''}" id="entry-${esc(r.id)}">${check('facts',r.id,r.label)}${embedded&&done?`<details><summary>回看取得提示</summary><p>${inline(r.tip)}</p>${detail}</details>`:`${r.location?'<p class="compact-location"><strong>'+esc(r.location)+'</strong></p>':''}<p class="compact-location">${inline(r.tip)}</p>${hasGuide?(embedded?detail:'<details id="guide-'+r.id+'"><summary>前置與取得步驟</summary>'+detail+'</details>'):''}`}${r.caveat?'<p class="'+(r.evidence==='conflicting'?'warning':'progress-note')+'">'+inline(r.caveat)+'</p>':''}<div class="row-footer">${embedded?'':routeFor(r)}<small>${esc(evidenceNames[r.evidence]||'待核對')}</small>${sources(r)}</div></article>`;}
function shipGuide(){return `<section class="chapter-guide"><h2>船藍圖查漏順序</h2><p>先核對船選單的名稱與 +／++，取得不等於已裝備。此處13個被動及4種炮彈是攻略索引，不能當作已核實的PS5金盃分母。</p><ol><li>先取 Long Island 鎖箱船體、Purricade 炮力與北部河道堡的彈藥升級；船炮可破木柵。</li><li>跟主線清 Ruined Castle、Orion、Centauri；Antares 三樓先走側梯下二樓取箱，不要求先打頂層Boss。</li><li>Heartpurreak 清兩隻敵人後檢查箱，Sunset 西側完成四藍石；救人魚時先清敵破門查箱，仍缺++再於八水點回報後回查。</li><li>最後補 Lonely Isle、Boar King、Meowtallicurse、The Undying、Cathulhu及巡航鴨船。Boss戰與獎勵箱／酒館領賞各自確認。</li></ol><p>打不動時先回收沿途箱並調整現有船裝；不用為了未知掉率反覆刷同一敵人。</p></section>`;}

function stats(){return '<section class="stats" aria-label="完成度">'+[['trophies','PSN 已確認',31],['equipment','原版裝備',96],['puzzle','解謎石',12],['secret','隱藏物',6],['spell','魔法',10]].map(([kind,label,total])=>{const rows=kind==='trophies'?data.trophies:data.entities.filter(e=>e.kind===kind),n=count(progress,kind==='trophies'?'trophies':'facts',rows);return `<a data-route class="stat-card" href="${href(kind==='trophies'?'trophies':'collections',{category:kind})}"><span>${label}</span><strong>${n} <small>/ ${total}</small></strong><span>${Math.round(n/total*100)}%</span><progress value="${n}" max="${total}" aria-label="${label}"></progress></a>`;}).join('')+'</section>';}
function road(){const c=chapter(),n=nextStep(progress,data),steps=data.steps.filter(s=>s.chapterId===c.id),claimed=data.entities.filter(e=>e.action==='claimed'&&!isDone(progress,'facts',e.id)&&isDone(progress,'facts',e.id.replace(/claimed$/,'defeated')));
 const targetStep=data.steps.find(s=>s.id===target||s.entityIds.includes(target));
 const selected=params().get('unit')||(targetStep?.chapterId===c.id?targetStep.id:'');
 let body=`<div class="page-heading"><div><h1>Cat Quest III · 遊玩路線</h1><p>順著海岸清區，回鎮領完獎勵，再出發。</p></div><button class="primary" id="continue">繼續下一步</button></div>${stats()}<p>下一步：${n?esc(n.label):'路線完成，繼續查漏'} · 尚缺 ${31-count(progress,'trophies',data.trophies)} 盃 · 重要未領賞 ${claimed.length} 張</p>${claimed.length?'<p class="warning">'+claimed.map(e=>link('collections',e.label,{category:'bounty',target:e.id})).join(' · ')+'</p>':''}<h2>${esc(c.label)}</h2><p>Easy 可用 · 完整劇透 · 閱讀、路線完成、收藏與跳盃各自確認</p><label>目前閱讀區域<select id="route-unit" class="route-picker">${options([['','本階段全部區域'],...steps.map(s=>[s.id,s.label])],selected)}</select></label>`;
 if(c.id==='stage-4')body+='<p class="warning">終章前確認三次 Aelius 完整對話；懸賞擊倒後仍要回酒館領賞。結局未跳可 Continue 回世界補對話後重打，不需立刻 NG+。</p>';
 for(const s of steps.filter(s=>!selected||s.id===selected)){const done=isDone(progress,'steps',s.id),expanded=!done||peeks.has(s.id)||target===s.id||s.entityIds.includes(target);body+=`<article class="row ${done?'done':''}" id="entry-${s.id}"><div class="row-heading"><h3 tabindex="-1">${esc(s.label)}</h3>${done?`<button data-peek="${s.id}">${expanded?'收合':'回看'}</button>`:''}</div>${check('steps',s.id,'完成此段路線')}<div class="row-body" ${expanded?'':'hidden'}>${markdown(s.body)}${s.id==='cq3-r08'?'<div class="warning">'+markdown(data.bookGuide)+'</div>':''}<h4>沿路逐項確認</h4>${s.id==='cq3-r18'?'<p>未核實位置的裝備集中於蒐集查漏，不視為終章掉落。</p>':''}${data.entities.filter(e=>s.entityIds.includes(e.id)&&(e.kind!=='equipment'||e.evidence!=='pending'||e.id===target)).map(e=>entity(e,true)).join('')}</div></article>`;}
 return body;}
function collections(){const rows=data.entities.filter(r=>r.kind===category&&(!subtype||r.category===subtype)&&match(r,'facts'));return `<h1>蒐集查漏</h1><p>原版清單與現版總量分開；勾選代表背包或任務紀錄已確認。</p><div class="pills">${Object.entries(kinds).map(([id,label])=>`<a data-category="${id}" href="${href('collections',{category:id})}" aria-current="${category===id}">${esc(label)}</a>`).join('')}</div>${category==='equipment'?`<label>裝備子類<select id="subtype">${options([['','全部類別'],['head','頭部'],['body','身體'],['melee','近戰'],['ranged','遠程'],['trinket','飾品']],subtype)}</select></label><p class="progress-note">原版96件均有取得提示；單源與來源差異逐筆標示，未經PS5實機核實。不以更新裝備或升級等級代替。</p>`:''}${['ship-passive','cannonpaw'].includes(category)?'<p class="warning">已收錄13個被動名稱及4種炮彈；不是已核實的金盃集合。</p>':''}${category==='bounty'?'<p>擊倒與回酒館領賞分別記錄。原版11張領賞不是現版必定跳盃保證。</p>':''}${['ship-passive','cannonpaw'].includes(category)?shipGuide():''}${toolbar()}<p>符合 ${rows.length} 項</p>${rows.map(r=>entity(r)).join('')||empty()}`;}
function evidence(t){const name=t.label,eq=data.entities.filter(e=>e.kind==='equipment'),kind=name==='Purroblem Solver'?'puzzle':name==='Secret Purrlunderer'?'secret':name==='Spellmewster'?'spell':null;
 if(/Armeowry/.test(name)){const n=count(progress,'facts',eq),threshold=name.includes('Amateur')?10:name.includes('Enjoyer')?40:null;return `${link('collections','查看裝備缺項',{category:'equipment'})} · 原版紀錄 ${n}/96；${threshold&&n>=threshold?'紀錄看似達標，請確認是否跳盃':'集合版本需核對'}`;}
 if(kind){const rows=data.entities.filter(e=>e.kind===kind),n=count(progress,'facts',rows);return link('collections','查看關聯缺項',{category:kind})+' · '+n+'/'+rows.length+(n===rows.length?' · 紀錄看似達標，請確認是否跳盃':'');}
 if(/Treasure/.test(name)){const threshold=name.includes('Rummeowger')?20:name.includes('Pouncer')?50:80;return '遊戲內觀察值 '+(progress.counters.chests?.value||0)+' / '+threshold+((progress.counters.chests?.value||0)>=threshold?' · 紀錄看似達標，請確認是否跳盃':'');}
 if(/Bounty|Furst Bounty/.test(name))return link('collections','查看領賞缺項',{category:'bounty'})+' · 原版已領 '+count(progress,'facts',data.entities.filter(e=>e.action==='claimed'))+'/11 · PS5現版條件需核對';
 if(/Ship/.test(name))return link('collections','核對船被動與版本',{category:'ship-passive'})+' · 精確金盃集合需核對';
 if(name==='Purrlatinum Seeker')return count(progress,'trophies',data.trophies.filter(e=>e.id!==t.id))+'/30 其他獎盃已確認；白金仍由玩家確認。';
 return routeFor(t);}
function trophies(){return `<h1>PS5 獎盃</h1><p>本體31座含白金。只記錄實際跳盃；收藏缺項可以與已跳盃並存。</p>${stats()}${toolbar()}${data.trophies.filter(t=>match(t,'trophies')).map(t=>`<article class="row" id="entry-${t.id}">${check('trophies',t.id,t.label)}<p>${esc(t.condition)}</p><p>${evidence(t)}</p>${sources(t)}</article>`).join('')||empty()}<h2>遊戲內觀察值</h2><p>手填數字與逐項清單不相加；不是自動讀取遊戲存檔。</p><div class="counter-grid">${[['chests','已開寶箱'],['equipment','獨特裝備（僅參考）']].map(([id,label])=>`<label>${label}<input id="counter-${id}" type="number" min="0" max="999999" step="1" data-counter="${id}" value="${progress.counters[id]?.value||0}"></label>`).join('')}</div>`;}
function backup(){return `<h1>資料與來源</h1>${translationPolicy()}<p>2026-11-27 · 本機模組1.3.0 · 尚未PS5實機驗收。未讀取遊戲存檔、PSN或Google Drive。</p><button data-open-backup>備份與還原</button><label>PS5 安裝版本（可選填）<input id="observed-version" maxlength="100" value="${esc(progress.settings.version?.value||'')}" placeholder="未實機核對版本"></label><h2>待映射的保留紀錄</h2><p>${Object.keys(progress.facts).filter(id=>!data.entities.some(e=>e.id===id)).map(esc).join(' · ')||'目前沒有未知項目'}。未知ID與欄位保留於匯出備份，不會因資料更新刪除。</p><h2>取得資料狀態</h2><p>本次針對${data.reviewedIds.length}個項目補查；具體結論與未解問題見每列「前置與取得步驟」。同地異名已釐清，不代表所有替代掉落或PS5現版條件已驗證。</p><p>${data.entities.filter(e=>e.kind==='equipment'&&e.location).length}/96件有取得提示；來源差異 ${data.entities.filter(e=>e.kind==='equipment'&&e.evidence==='conflicting').length} 件。多來源對照只代表網頁相符，未代表PS5實機確認。</p><h2>資料覆蓋</h2>${data.coverage.map(r=>'<p>'+r.map(esc).join(' · ')+'</p>').join('')}<h2>仍需核對的內容</h2>${data.gaps.map(r=>`<article class="row"><h3>${esc(r[0])}</h3><p>${esc(r[1])}</p><p>${esc(r[3])}</p></article>`).join('')}<h2>來源與版本</h2>${data.sources.filter(s=>!target||target==='source-'+s.id).map(s=>`<article class="row" id="entry-source-${s.id}"><h3 tabindex="-1">${esc(s.id)}</h3><p>${inline(s.body)}</p><p>${esc(s.note)}</p></article>`).join('')}`;}


function translationPolicy(){return '<section id="entry-translation-policy" class="translation-policy" tabindex="-1"><h2>中文譯名與原文對照</h2><p>'+esc(glossary.notice)+'</p><p>中文用來降低閱讀負擔；保留原文方便對照遊戲與外文攻略，兩種名稱都能搜尋。同物品沿用同一譯名與進度 ID。新譯名不代表取得地點、掉落條件或遊戲版本已核實。</p><p>目前詞彙表沒有已核對的官方中文項目。之後取得遊戲中文畫面或官方在地化證據時，優先更新顯示並保留舊譯作搜尋別名。少數專名採音譯，沒有額外推測效果。</p></section>';}

function reset(){subtype='';search='';status=view()==='roadmap'?'all':'pending';target='';}
function render(preserve=false){const openDetails=[...document.querySelectorAll('main details[open][id]')].map(el=>el.id);const active=document.activeElement,focusId=active?.id,y=scrollY,selection=active?.type==='search'?[active.selectionStart,active.selectionEnd]:null;const old=[...document.querySelectorAll('main article')],anchor=old.find(el=>el.getBoundingClientRect().bottom>0),anchorId=anchor?.id,top=anchor?.getBoundingClientRect().top;
 $('main').innerHTML=({roadmap:road,collections,trophies,backup}[view()])();
 const readingView=view();if(readingView==='collections'||readingView==='trophies')$('main').querySelector('h1')?.insertAdjacentHTML('afterend','<p class="translation-note">名稱採本站繁中參考譯名，原文以小字對照；尚未逐項核對遊戲官方中文。<a data-route href="'+href('backup',{target:'translation-policy'})+'">譯名說明</a></p>');
 chinese.decorate($('main'));
 if(preserve)for(const id of openDetails){const el=$(id);if(el?.tagName==='DETAILS')el.open=true;}
 $('phase-navigation').innerHTML=data.chapters.map(c=>`<li><a data-route href="${href('roadmap',{chapter:c.id})}" ${view()==='roadmap'&&chapter().id===c.id?'aria-current="location"':''}>${esc(c.label)}${c.steps?'<small>'+c.steps.filter(id=>isDone(progress,'steps',id)).length+' / '+c.steps.length+' 步驟</small>':''}</a></li>`).join('');
 document.querySelectorAll('[data-view]').forEach(a=>a.setAttribute('aria-current',a.dataset.view===view()?'page':'false'));
 chinese.decorate($('phase-navigation'));chinese.decorate(document.querySelector('.brand'));chinese.decorate(document.querySelector('.topbar'));
 if(target)$('main').insertAdjacentHTML('afterbegin',`<p>正在定位 ${esc(target)} <button data-reset>清除定位</button></p>`);
 if(preserve){const removed=old.findIndex(el=>el.contains(active));const neighbor=old.slice(removed+1).map(el=>$(el.id)).find(Boolean);const next=$(focusId)||(removed>=0?neighbor?.querySelector('input,button,a'):null)||$('main');next.focus({preventScroll:true});if(selection&&next.type==='search')next.setSelectionRange(...selection);const same=anchorId&&$(anchorId);scrollTo(0,same?y+same.getBoundingClientRect().top-top:y);}
}
function navigate(v,extra={}){history.pushState({},'',href(v,extra));reset();category=extra.category||'equipment';target=extra.target||'';if(target)status='all';render();if(matchMedia('(max-width:720px)').matches)$('menu').open=false;requestAnimationFrame(()=>{const el=target?$('entry-'+target):null;if(el){el.scrollIntoView();(el.querySelector('h3')||el.parentElement.closest('article')?.querySelector('h3')||el.querySelector('input')||el).focus({preventScroll:true});}else{scrollTo(0,0);$('main').focus({preventScroll:true});}});}
async function save(g,id,value){if(busy)return;busy=true;retry=()=>save(g,id,value);try{const result=await edit(store,g,id,value);progress=result.progress;if(g==='steps'&&value.done){peeks.delete(id);if(target===id||data.steps.find(s=>s.id===id)?.entityIds.includes(target)){target='';const u=new URL(location.href);u.searchParams.delete('target');u.searchParams.set('unit',id);history.replaceState({},'',u);}}lastUndo=result.undo;$('undo').hidden=false;$('retry').hidden=true;retry=null;message('已保存，可撤銷這一筆。');render(true);}catch(e){message('保存失敗：'+e.message+'；原資料保留，請重試。');$('retry').hidden=false;render(true);}finally{busy=false;drainUpdates();}}
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');try{a.href=url;a.download=name;a.click();}finally{setTimeout(()=>URL.revokeObjectURL(url),1000);}}
function openBackup(){$('backup-save-state').textContent='進度只保存於此瀏覽器；網站備份不是 PS5 遊戲存檔。';$('backup-dialog').showModal();}
$('backup-dialog').addEventListener('close',()=>$('open-backup').focus());
const safely=fn=>async e=>{try{await fn(e);}catch(error){message(error.message);}};
document.addEventListener('click',safely(async e=>{const cat=e.target.closest('[data-category]');if(cat){e.preventDefault();navigate('collections',{category:cat.dataset.category});return;}const a=e.target.closest('[data-route],[data-view]');if(a){e.preventDefault();const u=new URL(a.href);navigate(u.searchParams.get('view')||'roadmap',Object.fromEntries([...u.searchParams].filter(([k])=>k!=='view')));return;}const el=e.target.closest('button');if(!el)return;
 if(el.id==='open-backup'||el.hasAttribute('data-open-backup'))openBackup();
 if(el.id==='backup-close')$('backup-dialog').close();if(el.id==='import-open')$('import-file').click();
 if(el.hasAttribute('data-reset')){const u=new URL(location.href);u.searchParams.delete('target');history.replaceState({},'',u);reset();render();}
 if(el.dataset.peek){peeks.has(el.dataset.peek)?peeks.delete(el.dataset.peek):peeks.add(el.dataset.peek);render(true);}
 if(el.hasAttribute('data-all')){status='all';search='';target='';render(true);}
 if(el.id==='continue'){const n=nextStep(progress,data);navigate(n?'roadmap':'collections',n?{chapter:n.chapterId,target:n.id}:{});}
 if(el.id==='export-progress')download(envelope(await store.get()),'cat-quest-iii-progress-'+new Date().toISOString().replace(/[:.]/g,'-')+'.json');
 if(el.id==='export-all')download(await store.exportAll(),'cat-quest-iii-recovery.json');
 if(el.id==='undo'&&lastUndo){busy=true;try{progress=await undoEdit(store,lastUndo);lastUndo=null;el.hidden=true;message('已撤銷該筆，其他紀錄保留。');render(true);}finally{busy=false;drainUpdates();}}
 if(el.id==='retry'&&retry)await retry();
}));
document.addEventListener('change',safely(async e=>{const el=e.target;if(el.dataset.group){await save(el.dataset.group,el.dataset.id,{done:el.checked});return;}if(el.dataset.counter){if(!el.value.trim()||!Number.isSafeInteger(Number(el.value))||Number(el.value)<0||Number(el.value)>999999){message('計數須為非負整數。');return;}await save('counters',el.dataset.counter,{value:Number(el.value)});return;}
 if(el.id==='status'){status=el.value;render(true);}if(el.id==='subtype'){subtype=el.value;render(true);}if(el.id==='observed-version')await save('settings','version',{value:el.value});if(el.id==='route-unit'){const u=new URL(location.href);u.searchParams.set('unit',el.value);u.searchParams.delete('target');history.replaceState({},'',u);target='';render(true);}
 if(el.id==='import-file'&&el.files[0]){const file=el.files[0];$('backup-dialog').close();try{await preview(file);}finally{el.value='';}}
}));
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;render(true);}});
window.addEventListener('popstate',()=>{reset();category=params().get('category')||'equipment';target=params().get('target')||'';if(target)status='all';render();});

async function preview(file){
 if(file.size>10*1024*1024)throw Error('檔案超過 10 MB，停止匯入。');const sourceRaw=await file.text(),local=await store.raw(),localRaw=JSON.stringify(local);
 await store.archive({sourceRaw,localRaw,at:new Date().toISOString(),name:file.name});
 const incoming=importData(JSON.parse(sourceRaw));review={sourceRaw,localRaw,stamp:localRaw,rows:differences(local,incoming),downloaded:false,expired:false};
 $('diff-rows').innerHTML=review.rows.map((r,i)=>`<div class="diff-row"><label class="check"><input type="checkbox" data-diff="${i}" ${r.missing?'disabled':''}><span>${esc(r.group+' / '+r.id)}${r.missing?' · 來源缺少，保留本機':r.older?' · 來源較舊，需額外核對':''}</span></label><pre>本機：${esc(JSON.stringify(r.local)??'無紀錄')}\n來源：${esc(JSON.stringify(r.incoming)??'無紀錄')}</pre></div>`).join('')||'<p>兩端紀錄相同。</p>';
 $('import-status').textContent=review.rows.length+' 筆差異，未勾選項目保留本機。';$('import-ack').checked=false;$('import-ack').disabled=true;$('older-ack').checked=false;gate();$('import-dialog').showModal();
}
function gate(){$('import-apply').disabled=!review||review.expired||!review.downloaded||!$('import-ack').checked;}
$('choose-source').onclick=()=>document.querySelectorAll('[data-diff]:not(:disabled)').forEach(x=>x.checked=true);
$('choose-local').onclick=()=>document.querySelectorAll('[data-diff]').forEach(x=>x.checked=false);
$('download-recovery').onclick=async()=>{try{if(review.expired)throw Error('預覽已過期');download({gameId,recoveryBundle:{localRaw:review.localRaw,sourceRaw:review.sourceRaw},progress:JSON.parse(review.localRaw)},'cat-quest-iii-before-import.json');review.downloaded=true;$('import-ack').disabled=false;$('import-status').textContent='備份已開始下載，請確認檔案保存後勾選。';}catch(e){review.downloaded=false;$('import-ack').checked=false;$('import-ack').disabled=true;$('import-status').textContent='備份失敗：'+e.message;}gate();};
$('import-ack').onchange=gate;
$('import-apply').onclick=async()=>{if(!review||$('import-apply').disabled)return;const selected=new Set([...document.querySelectorAll('[data-diff]:checked')].map(el=>{const r=review.rows[Number(el.dataset.diff)];return r.group+'/'+r.id;}));busy=true;try{await store.checkpoint('匯入前');progress=await store.update(p=>applyDifferences(p,review.rows,selected,$('older-ack').checked),review.stamp);lastUndo=null;$('undo').hidden=true;review=null;$('import-dialog').close();message('已套用選定差異，原文與快照均保留。');render(true);}catch(e){$('import-status').textContent=e.message;if(e.message.includes('過期'))review.expired=true;gate();}finally{busy=false;drainUpdates();}};
$('import-close').onclick=()=>{$('import-dialog').close();review=null;};
$('import-dialog').addEventListener('close',()=>{review=null;$('open-backup').focus();});


try{const response=await fetch('./data.json',{cache:'no-store'});if(!response.ok)throw Error('攻略讀取失敗：'+response.status);data=await response.json();searchIndex=new Map([...data.entities,...data.steps,...data.trophies].map(r=>{const original=JSON.stringify(r);return [r.id,original+' '+chinese.plain(original)];}));if(data.gameId!==gameId||data.steps.length!==19||data.trophies.length!==31)throw Error('攻略資料不完整');progress=await store.open();ready=true;reset();category=params().get('category')||'equipment';target=params().get('target')||'';if(target)status='all';$('menu').open=matchMedia('(min-width:721px)').matches;render();message('進度已載入，操作保存於此瀏覽器。');if(target)requestAnimationFrame(()=>$('entry-'+target)?.scrollIntoView());}catch(e){$('main').innerHTML='<h1>無法載入</h1><p>'+esc(e.message)+'</p><p>原有紀錄未歸零，已停止寫入。</p><button id="reload">重新載入</button><button id="raw-export">下載原始封存</button>';$('reload').onclick=()=>location.reload();$('raw-export').onclick=safely(async()=>download(await store.exportAll(),'cat-quest-iii-unreadable-original.json'));message('載入失敗，請先保存原始資料。');}
